ll,"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"24,600","type":"text"}]}]},{"type":"tableCell","attrs":{"align":null,"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","attrs":{"textAlign":null}}]},{"type":"tableCell","attrs":{"align":null,"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"(24,600)","type":"text"}]}]},{"type":"tableCell","attrs":{"align":null,"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","attrs":{"textAlign":null}}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"align":null,"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"Attributable to SEGHPL's owners","type":"text","marks":[{"type":"bold"}]}]}]},{"type":"tableCell","attrs":{"align":null,"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"85,160","type":"text","marks":[{"type":"bold"}]}]}]},{"type":"tableCell","attrs":{"align":null,"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","attrs":{"textAlign":null}}]},{"type":"tableCell","attrs":{"align":null,"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","attrs":{"textAlign":null}}]},{"type":"tableCell","attrs":{"align":null,"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","attrs":{"textAlign":null}}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"align":null,"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"NCI","type":"text","marks":[{"type":"bold"}]}]}]},{"type":"tableCell","attrs":{"align":null,"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","attrs":{"textAlign":null}}]},{"type":"tableCell","attrs":{"align":null,"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"4,840","type":"text","marks":[{"type":"bold"}]}]}]},{"type":"tableCell","attrs":{"align":null,"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"–","type":"text"}]}]},{"type":"tableCell","attrs":{"align":null,"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"–","type":"text"}]}]}]}]},{"type":"blockquote","attrs":{"variant":"quote"},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"Check: 85,160 + 4,840 = 90,000 = 20,000 + 30,000 + 5,000 + 40,000 − 3,000 − 2,000","type":"text"}]}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"The downstream gain falls wholly on the parent, because the parent recorded it. The upstream profit was recorded by SEGPL, so its 10 percent outside owners bear 10% × 2,000 = 200 of it through the lower NCI. The NCI in Holdings BV is zero, yet its outside owners still exist. They sit one level up, as SEGPL's 10 percent, and take 10% × 51% × 40,000 = 2,040 of Holdings BV's profit.","type":"text"}]},{"type":"blockquote","attrs":{"variant":"quote"},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"Effective-interest check: SEGHPL takes 94.9% × 40,000 = 37,960 of Holdings BV's profit; 37,960 + 2,040 = 40,000","type":"text"}]}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"The worksheet removes both unrealised profits first:","type":"text"}]},{"type":"blockquote","attrs":{"variant":"quote"},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"Dr Gain on sale of land 3,000 / Cr Land 3,000","type":"text"}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"Dr Cost of sales 2,000 / Cr Inventories 2,000","type":"text"}]}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"On the parent's books.","type":"text","marks":[{"type":"bold"}]},{"text":" Under the equity method the parent's profit equals the controlling share, 85,160. In the notes, Pet's income from Sal is 70% × 39,000 − 70% × 5,000 upstream − 10,000 downstream = 13,800.","type":"text"}]},{"type":"heading","attrs":{"level":2,"textAlign":null},"content":[{"text":"3. Parent shares held by a subsidiary","type":"text"}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"Parent shares held by a subsidiary are, for the group, shares it has bought back from itself. A ","type":"text"},{"text":"mutual holding","type":"text","marks":[{"type":"italic"}]},{"text":" exists when two affiliated companies each hold shares in the other. The first case in the notes (section C) is a subsidiary owning shares of its parent. From the group's view those shares are not outstanding. The group has bought back part of itself, and the question is how to show that and how to split profit.","type":"text"}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"In the notes' example Pam buys 90 percent of Son on 1 January 2016 for 540,000, when Son's equity is 600,000 (capital 400,000, retained earnings 200,000), so there is no goodwill. Son buys 10 percent of Pam on 5 January 2016 for 140,000, when Pam's equity is 1,400,000 (capital 1,000,000 in shares of 10 par, retained earnings 400,000). Separate profits for 2016 are 100,000 for Pam and 60,000 for Son, with no dividends.","type":"text"}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"The treasury stock approach","type":"text","marks":[{"type":"bold"}]},{"text":" treats Pam's shares held by Son as if Pam had bought them back. Son's investment in Pam is reclassified to treasury shares at cost and deducted from consolidated equity, and the mutual holding is otherwise ignored in profit. Son has no income from Pam in 2016.","type":"text"}]},{"type":"blockquote","attrs":{"variant":"quote"},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"Pam's income from Son = 90% × 60,000 = 54,000; Pam's profit = 100,000 + 54,000 = 154,000","type":"text"}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"NCI share = 10% × 60,000 = 6,000; NCI at year end = 10% × (600,000 + 60,000) = 66,000","type":"text"}]}]},{"type":"table","content":[{"type":"tableRow","content":[{"type":"tableHeader","attrs":{"align":null,"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"Worksheet entry (2016)","type":"text"}]}]},{"type":"tableHeader","attrs":{"align":null,"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"Dr","type":"text"}]}]},{"type":"tableHeader","attrs":{"align":null,"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"Cr","type":"text"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"align":null,"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"Income from Son / Investment in Son","type":"text"}]}]},{"type":"tableCell","attrs":{"align":null,"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"54,000","type":"text"}]}]},{"type":"tableCell","attrs":{"align":null,"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"54,000","type":"text"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"align":null,"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"Capital stock and retained earnings, Son / Investment in Son; NCI","type":"text"}]}]},{"type":"tableCell","attrs":{"align":null,"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"600,000","type":"text"}]}]},{"type":"tableCell","attrs":{"align":null,"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"540,000; 60,000","type":"text"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"align":null,"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"NCI share of profit / NCI","type":"text"}]}]},{"type":"tableCell","attrs":{"align":null,"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"6,000","type":"text"}]}]},{"type":"tableCell","attrs":{"align":null,"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"6,000","type":"text"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"align":null,"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"Treasury shares / Investment in Pam","type":"text"}]}]},{"type":"tableCell","attrs":{"align":null,"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"140,000","type":"text"}]}]},{"type":"tableCell","attrs":{"align":null,"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"140,000","type":"text"}]}]}]}]},{"type":"blockquote","attrs":{"variant":"quote"},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"Consolidated equity = 1,000,000 + 554,000 − 140,000 + 66,000 = 1,480,000 = other assets of 960,000 + 520,000","type":"text"}]}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"The conventional approach","type":"text","marks":[{"type":"bold"}]},{"text":" treats Pam's shares held by Son as constructively retired, and lets Son's outside owners share in Pam's profit through Son's 10 percent stake. Then neither company's profit on an equity basis can be found first, because each includes a share of the other. The notes solve it with two equations.","type":"text"}]},{"type":"blockquote","attrs":{"variant":"quote"},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"P = Pam's profit on a consolidated basis, including mutual profit; S = the same for Son","type":"text"}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"P = 100,000 + 0.9S","type":"text"}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"S = 60,000 + 0.1P","type":"text"}]}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"Substituting:","type":"text"}]},{"type":"blockquote","attrs":{"variant":"quote"},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"P = 100,000 + 0.9 × (60,000 + 0.1P) = 154,000 + 0.09P","type":"text"}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"0.91P = 154,000; P = 169,230.77","type":"text"}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"S = 60,000 + 0.1 × 169,230.77 = 76,923.08","type":"text"}]}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"P + S = 246,153.85, far above the combined separate profit of 160,000, because each figure includes the other's share. Each result is then multiplied by the share held outside the pair:","type":"text"}]},{"type":"blockquote","attrs":{"variant":"quote"},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"Profit attributable to Pam's own shareholders = 90% × 169,230.77 = 152,307.69","type":"text"}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"NCI = 10% × 76,923.08 = 7,692.31","type":"text"}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"Check: 152,307.69 + 7,692.31 = 160,000","type":"text"}]}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"Pam's equity-method income from Son is 90 percent of S less 10 percent of P, the part of Pam's own profit that belongs to Son: 69,230.77 − 16,923.08 = 52,307.69. On Pam's own books the conventional approach also debits capital stock 100,000 and retained earnings 40,000 and credits the investment in Son 140,000, so Pam's equity method shows 900,000 of capital and the investment falls to 400,000 before income.","type":"text"}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"The second year.","type":"text","marks":[{"type":"bold"}]},{"text":" In 2017 Pam earns 120,000 separately and pays dividends of 60,000, 6,000 of them to Son. Son earns 80,000 and pays 40,000.","type":"text"}]},{"type":"table","content":[{"type":"tableRow","content":[{"type":"tableHeader","attrs":{"align":null,"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","attrs":{"textAlign":null}}]},{"type":"tableHeader","attrs":{"align":null,"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"Treasury stock approach","type":"text"}]}]},{"type":"tableHeader","attrs":{"align":null,"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"Conventional approach","type":"text"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"align":null,"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"Logic","type":"text"}]}]},{"type":"tableCell","attrs":{"align":null,"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"Parent shares held by Son are bought back; Son's stake earns nothing for the group","type":"text"}]}]},{"type":"tableCell","attrs":{"align":null,"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"Parent shares are ret