t":"152,307.69","type":"text"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"align":null,"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"NCI share of 2016 profit","type":"text"}]}]},{"type":"tableCell","attrs":{"align":null,"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"6,000","type":"text"}]}]},{"type":"tableCell","attrs":{"align":null,"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"7,692.31","type":"text"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"align":null,"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"Parent's share of 2017 profit","type":"text"}]}]},{"type":"tableCell","attrs":{"align":null,"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"120,000 + 90% × 86,000 − 6,000 = 191,400","type":"text"}]}]},{"type":"tableCell","attrs":{"align":null,"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"90% × 210,989.01 = 189,890.11","type":"text"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"align":null,"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"NCI share of 2017 profit","type":"text"}]}]},{"type":"tableCell","attrs":{"align":null,"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"10% × 86,000 = 8,600","type":"text"}]}]},{"type":"tableCell","attrs":{"align":null,"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"10% × 101,098.90 = 10,109.89","type":"text"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"align":null,"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"Equity presentation","type":"text"}]}]},{"type":"tableCell","attrs":{"align":null,"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"Capital 1,000,000 less treasury shares 140,000","type":"text"}]}]},{"type":"tableCell","attrs":{"align":null,"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"Capital 900,000; retained earnings reduced by 40,000","type":"text"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"align":null,"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"Parent's equity, end 2016","type":"text"}]}]},{"type":"tableCell","attrs":{"align":null,"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"1,000,000 + 554,000 − 140,000 = 1,414,000","type":"text"}]}]},{"type":"tableCell","attrs":{"align":null,"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"900,000 + 512,307.69 = 1,412,307.69","type":"text"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"align":null,"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"NCI, end 2016","type":"text"}]}]},{"type":"tableCell","attrs":{"align":null,"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"66,000","type":"text"}]}]},{"type":"tableCell","attrs":{"align":null,"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"60,000 + 7,692.31 = 67,692.31","type":"text"}]}]}]}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"Both columns hold the same consolidated net assets of 1,480,000 at the end of 2016. Only the split between the parent's owners and the NCI differs. The conventional approach gives NCI more, because Son's outside owners are treated as owning 10% × 10% = 1 percent of Pam.","type":"text"}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"Converting retained earnings.","type":"text","marks":[{"type":"bold"}]},{"text":" The notes reuse the same equations to put two years of undistributed earnings onto an equity basis. The separate increases in net assets from 2016 to 2017 are 196,000 for Pam (100,000 + 120,000 − 60,000 + 36,000 received) and 106,000 for Son (60,000 + 80,000 − 40,000 + 6,000 received).","type":"text"}]},{"type":"blockquote","attrs":{"variant":"quote"},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"P = 196,000 + 0.9S; S = 106,000 + 0.1P, so P = 320,219.78 and S = 138,021.98","type":"text"}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"To Pam's retained earnings: 90% × 320,219.78 = 288,197.80; to NCI: 10% × 138,021.98 = 13,802.20","type":"text"}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"288,197.80 + 13,802.20 = 302,000","type":"text"}]}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"Which approach PSAK permits.","type":"text","marks":[{"type":"bold"}]},{"text":" PSAK 232 ","type":"text"},{"text":"Instrumen Keuangan: Penyajian","type":"text","marks":[{"type":"italic"}]},{"text":" (formerly PSAK 50, IAS 32) para. 33 deducts the cost of an entity's own equity instruments that it reacquires from equity, records no gain or loss on their purchase, sale, issue or cancellation, and states that such shares may be acquired and held by the entity \"or by other members of the consolidated group\". PSAK 110 para. B86 eliminates intragroup equity in full. Together they make the parent's shares held by a subsidiary treasury shares of the group, shown at cost as a deduction. That is the treasury stock approach's presentation, and it rules out the conventional approach's balance sheet, with capital cut to 900,000 and retained earnings to 360,000 as if the shares were cancelled. Para. 33 does not say whether Son's NCI shares in Pam's profit through those shares, so the conventional profit split is a question PSAK leaves open. Earnings per share follow the presentation. Under PSAK 233 (formerly PSAK 56, IAS 33) the 10,000 shares held by Son are not outstanding, so 2016 earnings per share are 154,000 / 90,000 = 1.711, ignoring the four days before Son's purchase, against 152,307.69 / 90,000 = 1.692 under the conventional split.","type":"text"}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"A second attribution point is open as well. Beams gives NCI 10 percent of Son's whole 2017 profit of 86,000, including the 6,000 dividend received from Pam. On a strict group view that dividend is not income, so NCI's share of profit would be 10% × 80,000 = 8,000, and the 600 by which the dividend enlarges NCI's claim would be a transfer within equity from the parent's owners. NCI ends at 70,600 either way. PSAK gives no explicit guidance on this split.","type":"text"}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"In Indonesia the case is rare.","type":"text","marks":[{"type":"bold"}]},{"text":" UU 40/2007 on limited companies art. 36(1) forbids a company to issue shares to be owned by itself or by another company whose shares it owns directly or indirectly. Shares obtained by operation of law, gift or bequest are exempt (art. 36(2)) but must be transferred within one year (art. 36(3)). BRPT's FS show no subsidiary holding BRPT shares. PT Barito Pacific Lumber, which holds 0.58 percent, belongs to Prajogo Pangestu, not to the group (Note 28, PDF p. 211; Note 45, PDF p. 235). BRPT's treasury shares of 1,600 consist of shares the Company bought back itself (Note 30, PDF pp. 212–213).","type":"text"}]},{"type":"heading","attrs":{"level":2,"textAlign":null},"content":[{"text":"4. Subsidiaries that hold each other","type":"text"}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"When two subsidiaries own each other, the treasury stock approach has nothing to work on, because neither holding is in the parent. The notes' case (section D): Pam owns 80 percent of Set, Set owns 70 percent of Ton, and Ton owns 10 percent of Set. Set's outside owners hold the remaining 10 percent and Ton's hold 30 percent. Separate profits for 2018, excluding income from affiliates, are 112,000 for Pam, 51,000 for Set and 40,000 for Ton. Three companies give three equations.","type":"text"}]},{"type":"blockquote","attrs":{"variant":"quote"},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"P = 112,000 + 0.8S","type":"text"}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"S = 51,000 + 0.7T","type":"text"}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"T = 40,000 + 0.1S","type":"text"}]}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"Solving the pair that loops first:","type":"text"}]},{"type":"blockquote","attrs":{"variant":"quote"},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"S = 51,000 + 0.7 × (40,000 + 0.1S) = 79,000 + 0.07S","type":"text"}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"0.93S = 79,000; S = 84,946.24","type":"text"}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"T = 40,000 + 0.1 × 84,946.24 = 48,494.62","type":"text"}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"P = 112,000 + 0.8 × 84,946.24 = 179,956.99","type":"text"}]}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"Pam's shares are held only by its own shareholders, so P is the controlling share. NCI is each subsidiary's outside percentage times its equation result:","type":"text"}]},{"type":"blockquote","attrs":{"variant":"quote"},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"NCI in Set = 10% × 84,946.24 = 8,494.62","type":"text"}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"NCI in Ton = 30% × 48,494.62 = 14,548.39","type":"text"}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"Check: 179,956.99 + 8,494.62 + 14,548.39 = 203,000 = 112,000 + 51,000 + 40,000","type":"text"}]}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"Pam's equity-method income from Set is 80% × 84,946.24 = 67,956.99, and Set's from Ton is 70% × 48,494.62 = 33,946.24. Ton carries its 10 percent of Set at cost and records only its 3,000 dividend, which the worksheet eliminates.","type":"text"}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"The same answer as effective interests.","type":"text","marks":[{"type":"bold"}]},{"text":" The equations can be turned around to say what share of each company's own profit reaches each owner. Write the holdings as a matrix W, invert (I − W) with Python, and multiply each column of the inverse by that company's outside share:","type":"text"}]},{"type":"table","content":[{"type":"tableRow","content":[{"type":"tableHeader","attrs":{"align":null,"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"Share of each company's own profit going to","type":"text"}]}]},{"type":"tableHeader","attrs":{"align":null,"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"Set's profit","type":"text"}]}]},{"type":"tableHeader","attrs":{"align":null,"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"Ton's profit","type":"text"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"align":null,"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"Pam's owners","type":"text"}]}]},{"type":"tableCell","attrs":{"align":null,"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"0.8 / 0.93 = 86.02%","type":"text"}]}]},{"type":"tableCell","attrs":{"align":null,"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"0.8 × 0.7 / 0.93 = 60.22%","type":"text"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"align":null,"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"Set's outside owners (10%)","type":"text"}]}]},{"type":"tableCell","attrs":{"align":null,"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"0.1 / 0.93 = 10.75%","type":"text"}]}]},{"type":"tableCell","attrs":{"align":null,"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"0.07 / 0.93 = 7.53%","type":"text"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"align":null,"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"Ton's outside owners (30%)","type":"text"}]}]},{"type":"tableCell","attrs":{"align":null,"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"0.03 / 0.93 = 3.23%","type":"text"}]}]},{"type":"tableCell","attrs":{"align":null,"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"0.3 / 0.93 = 32.26%","type":"text"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"align":null,"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"Total","type":"text"}]}]},{"type":"tableCell","attrs":{"align":null,"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"100%","type":"text"}]}]},{"type":"tableCell","attrs":{"align":null,"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"100%","type":"text"}]}]}]}]},{"type":"blockquote","attrs":{"variant":"quote"},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"Pam = 112,000 + (0.8 / 0.93) × 51,000 + (0.56 / 0.93) × 40,000 = 179,956.99","type":"text"}]}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"The divisor 0.93 = 1 − 0.7 × 0.1 is the loop: of each dollar Set earns, 7 cents comes back to Set through Ton. PSAK 110 treats Ton's 10 percent of Set as intragroup equity to be eliminated (para. B86), so Set's NCI is the outside 10 percent only. The equations remain the arithmetic for attributing profit.","type":"text"}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"The notes' goodwill is grossed up from the parent's price.","type":"text","marks":[{"type":"bold"}]},{"text":" The notes give goodwill of 25,000 on Pam's 260,000 for 80 percent of Set's 300,000 equity, and 10,000 on Set's 112,000 for 70 percent of Ton's 150,000. Both gross up the price: 260,000 / 80% − 300,000 = 25,000. PSAK 103 ","type":"text"},{"text":"Kombinasi Bisnis","type":"text","marks":[{"type":"italic"}]},{"text":" (formerly PSAK 22, IFRS 3) para. 19 measures NCI at its own fair value, which also gives full goodwill but not by grossing up a price that includes a control premium, or at its share of net assets. Under the second option goodwill would be 260,000 − 80% × 300,000 = 20,000 and 112,000 − 70% × 150,000 = 7,000.","type":"text"}]},{"type":"heading","attrs":{"level":2,"textAlign":null},"content":[{"text":"5. Effective interests in a real multi-layer group","type":"text"}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"In a real group the same rules apply, but disclosure tables mix direct and effective percentages. BRPT's Note 1d shows, for each subsidiary, the holding by the company directly above it. BREN's Note 1 shows BREN's effective interest. Combining the two (BRPT FS 2025, Note 1d, PDF pp. 24–28; BREN FS 2025, Note 1, PDF p. 18):","type":"text"}]},{"type":"table","content":[{"type":"tableRow","content":[{"type":"tableHeader","attrs":{"align":null,"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"Company","type":"text"}]}]},{"type":"tableHeader","attrs":{"align":null,"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"Path","type":"text"}]}]},{"type":"tableHeader","attrs":{"align":null,"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"Effective interest of BREN","type":"text"}]}]},{"type":"tableHeader","attrs":{"align":null,"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"Effective interest of BRPT","type":"text"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"align":null,"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"Chandra Asri Pacific (CAP)","type":"text"}]}]},{"type":"tableCell","attrs":{"align":null,"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"BRPT 34.63% + Marigold (100% BRPT) 3.92%","type":"text"}]}]},{"type":"tableCell","attrs":{"align":null,"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"–","type":"text"}]}]},{"type":"tableCell","attrs":{"align":null,"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"38.55%","type":"text"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"align":null,"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"Aster Chemical and Energy (ACE)","type":"text"}]}]},{"type":"tableCell","attrs":{"align":null,"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"CAP → CATCO 100% → CAC 100% → CAPGC 80% → ACE 100%","type":"text"}]}]},{"type":"tableCell","attrs":{"align":null,"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"–","type":"text"}]}]},{"type":"tableCell","attrs":{"align":null,"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"38.55% × 80% = 30.84%","type":"text"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"align":null,"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"Krakatau Chandra Energi","type":"text"}]}]},{"type":"tableCell","attrs":{"align":null,"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"CAP → CDI 60% → KCE 70%","type":"text"}]}]},{"type":"tableCell","attrs":{"align":null,"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"–","type":"text"}]}]},{"type":"tableCell","attrs":{"align":null,"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"38.55% × 60% × 70% = 16.19%","type":"text"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"align":null,"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"Holdings BV","type":"text"}]}]},{"type":"tableCell","attrs":{"align":null,"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"section 2","type":"text"}]}]},{"type":"tableCell","attrs":{"align":null,"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"94.90%","type":"text"}]}]},{"type":"tableCell","attrs":{"align":null,"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"64.67% × 94.90% = 61.37%","type":"text"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"align":null,"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"Salak and Darajat operating companies","type":"text"}]}]},{"type":"tableCell","attrs":{"align":null,"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"Holdings BV → SEGSDBV","type":"text"}]}]},{"type":"tableCell","attrs":{"align":null,"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"80.91%","type":"text"}]}]},{"type":"tableCell","attrs":{"align":null,"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"64.67% × 80.91% = 52.32%","type":"text"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"align":null,"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"Wayang Windu (SEG-WW)","type":"text"}]}]},{"type":"tableCell","attrs":{"align":null,"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"SEGHPL → SEGPL 90%","type":"text"}]}]},{"type":"tableCell","attrs":{"align":null,"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"90.00%","type":"text"}]}]},{"type":"tableCell","attrs":{"align":null,"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"64.67% × 90.00% = 58.20%","type":"text"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"align":null,"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"SEG Drilling Services","type":"text"}]}]},{"type":"tableCell","attrs":{"align":null,"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"SEGPL 51% + SEGSDBV 49%","type":"text"}]}]},{"type":"tableCell","attrs":{"align":null,"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"90% × 51% + 80.91% × 49% = 85.55%","type":"text"}]}]},{"type":"tableCell","attrs":{"align":null,"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"55.33%","type":"text"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"align":null,"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"Suoh Sekincau (SEGSS)","type":"text"}]}]},{"type":"tableCell","attrs":{"align":null,"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"BRPT 5% direct + SEGSDBV 95%","type":"text"}]}]},{"type":"tableCell","attrs":{"align":null,"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"95% × 80.91% = 76.86%","type":"text"}]}]},{"type":"tableCell","attrs":{"align":null,"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"5% + 64.67% × 76.86% = 54.71%","type":"text"}]}]}]}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"Three things follow. First, BRPT consolidates CAP, ACE and Krakatau Chandra Energi with effective interests of 38.55, 30.84 and 16.19 percent. BRPT explains its control of CAP by the composition of CAP's board, which gives it power over CAP's relevant activities (Note 4, PDF p. 112). Each step below CAP is a majority holding, so control passes down.","type":"text"}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"Second, BREN's 80.91 percent for SEGSDBV is more than the main path gives. Holdings BV owns 80.20 percent of SEGSDBV (BREN FS 2025, Note 1, PDF p. 26), and 94.90% × 80.20% = 76.11%. The difference matches SEGHPL's 24.24 percent purchase of ACEHI Netherlands B.V., which BRPT says raised SEGHPL's indirect ownership of SEGSDBV to 80.91 percent (BRPT FS 2025, Note 31, PDF p. 218): 24.24% × 19.80% = 4.80%, and 76.11% + 4.80% = 80.91%.","type":"text"}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"Third, the 5 percent \"direct ownership\" of SEGSS, Darajat Geothermal Indonesia (DGI), Star Energy Geothermal Indonesia (SEGI) and Halmahera (SEGH) is held outside BREN's group. BREN's own notes name Barito Pacific as the 5 percent holder of SEGI and SEGH (BREN FS 2025, Note 1, PDF pp. 25–26). BREN's effective figures (76.86 percent and 85.50 percent) equal 95 percent of the path above, so in BREN's own statements that 5 percent is NCI, and in BRPT's statements it is the parent's own. The same shares are NCI at one level of reporting and controlling interest at the next. A structure like this keeps two shareholders in each Indonesian limited company, which UU 40/2007 art. 7(1) and 7(5)–(6) require.","type":"text"}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"A treasury share at the subsidiary moves the effective interest.","type":"text","marks":[{"type":"bold"}]},{"text":" BREN bought back 6,000,000 of its own shares in 2025 (Note 31, PDF p. 217). BRPT holds 86,514,146,666 of BREN's 133,786,220,000 issued shares (BREN FS 2025, Note 19a, PDF p. 114).","type":"text"}]},{"type":"blockquote","attrs":{"variant":"quote"},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"On issued shares: 86,514,146,666 / 133,786,220,000 = 64.6660%","type":"text"}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"On outstanding shares: 86,514,146,666 / (133,786,220,000 − 6,000,000) = 64.6689%","type":"text"}]}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"Profit is attributed on outstanding shares, because treasury shares carry no claim, and here the two bases differ by 0.003 percentage points. BRPT records the buybacks by BREN and CAP as transactions with NCI: of the 5,163 paid (1,930 by BREN and 3,233 by CAP), 2,495 reduces other equity components and 2,668 reduces NCI (statement of changes in equity, PDF p. 18).","type":"text"}]},{"type":"heading","attrs":{"level":2,"textAlign":null},"content":[{"text":"6. Complex structures across industries","type":"text"}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"Banks and structured entities.","type":"text","marks":[{"type":"bold"}]},{"text":" A bank may consolidate a securitisation vehicle or a fund in which it owns no shares at all, because PSAK 110 tests control through power and variable returns, not equity. Its effective equity interest may be zero, and the vehicle's equity is then NCI or, if redeemable, a liability (FSLI 25 section 9).","type":"text"}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"Investment entities.","type":"text","marks":[{"type":"bold"}]},{"text":" A parent that qualifies as an investment entity does not consolidate its subsidiaries; it measures them at fair value through profit or loss (PSAK 110 para. 31), except subsidiaries that provide investment-related services (para. 32). A venture fund's layered portfolio companies therefore never enter a chain calculation. A non-investment parent above it still consolidates everything, including what the fund holds (para. 33).","type":"text"}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"Conglomerate pyramids and the two-shareholder rule.","type":"text","marks":[{"type":"bold"}]},{"text":" Indonesian groups stack listed companies, as BRPT does with BREN, CAP and Chandra Daya Investasi, and many subsidiaries carry a small stake held by a sister company to keep two shareholders. Each listed layer adds outsiders, and each small stake is NCI in a sub-group's statements but not in the group's.","type":"text"}]},{"type":"heading","attrs":{"level":2,"textAlign":null},"content":[{"text":"7. Presentation and analysis: Barito Pacific's Note 34","type":"text"}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"BRPT discloses NCI by sub-group, its movement, and summarised financial information for the two subsidiaries with material NCI (Note 34, PDF pp. 220–221), as PSAK 112 (formerly PSAK 67, IFRS 12) para. 12 asks.","type":"text"}]},{"type":"table","content":[{"type":"tableRow","content":[{"type":"tableHeader","attrs":{"align":null,"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"NCI in","type":"text"}]}]},{"type":"tableHeader","attrs":{"align":null,"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"31 Dec 2025","type":"text"}]}]},{"type":"tableHeader","attrs":{"align":null,"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"31 Dec 2024","type":"text"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"align":null,"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"CAP and its subsidiaries","type":"text"}]}]},{"type":"tableCell","attrs":{"align":null,"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"3,178,669","type":"text"}]}]},{"type":"tableCell","attrs":{"align":null,"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"1,918,694","type":"text"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"align":null,"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"BREN and its subsidiaries","type":"text"}]}]},{"type":"tableCell","attrs":{"align":null,"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"471,951","type":"text"}]}]},{"type":"tableCell","attrs":{"align":null,"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"397,199","type":"text"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"align":null,"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"Others","type":"text"}]}]},{"type":"tableCell","attrs":{"align":null,"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"151,596","type":"text"}]}]},{"type":"tableCell","attrs":{"align":null,"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"144,263","type":"text"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"align":null,"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"Total","type":"text","marks":[{"type":"bold"}]}]}]},{"type":"tableCell","attrs":{"align":null,"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"3,802,216","type":"text","marks":[{"type":"bold"}]}]}]},{"type":"tableCell","attrs":{"align":null,"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"2,460,156","type":"text","marks":[{"type":"bold"}]}]}]}]}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"The BREN line is two layers of outsiders.","type":"text","marks":[{"type":"bold"}]},{"text":" BREN's own NCI is 246,651, mostly ACEHI (176,028) and DGA SEG B.V. (50,971) inside the Star Energy chain (BREN FS 2025, Note 20, PDF p. 116). Above that sit BREN's own outside shareholders. BREN's equity attributable to its owners, 636,868 (PDF p. 12), is already net of its treasury shares, so their share is measured on outstanding shares, 1 − 64.66886% = 35.33114% (section 5).","type":"text"}]},{"type":"blockquote","attrs":{"variant":"quote"},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"35.33114% × 636,868 = 225,013","type":"text"}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"225,013 + 246,651 = 471,664, against BRPT's 471,951; difference 287","type":"text"}]}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"The difference of 287 is 0.06 percent of the line, and likely reflects consolidation adjustments made at BRPT's level that BREN's statements do not carry. BRPT does not reconcile the two. The same layering explains profit: of BREN's profit of 165,137, BRPT's owners take 64.6689% × 132,198 = 85,491, and NCI at BRPT's level is 32,939 + 46,707 = 79,646.","type":"text"}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"Attributable profit follows effective interests, not the top holding.","type":"text","marks":[{"type":"bold"}]},{"text":" BRPT's owners took 30.3 percent of 2025 profit (489,807 of 1,615,634). CAP produced most of the group's profit (1,447,986 before intragroup elimination, Note 34), and BRPT's effective interest in CAP is 38.55 percent (34.63 direct plus 3.92 through Marigold). A rough bridge, 38.55% × 1,447,986 + 85,491 = 643,690, leaves 153,883 above the owners' actual 489,807. Part of the gap comes from outsiders below CAP, such as the 20 percent of CAPGC above Aster and the 40 percent of CDI; the rest is parent-level costs and consolidation adjustments that the FS do not split. Anyone valuing BRPT from consolidated profit would overstate what its shareholders earn by a factor of 1,615,634 / 489,807 = 3.3.","type":"text"}]},{"type":"heading","attrs":{"level":2,"textAlign":null},"content":[{"text":"8. Related essays","type":"text"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"FSLI 25 ","type":"text"},{"text":"non-controlling-interest","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener noreferrer nofollow","href":"/accounting/fsli/non-controlling-interest","class":"text-primary underline cursor-pointer hover:text-primary/80","title":null,"target":"_blank"}}]},{"text":": the control test, NCI measurement, attribution, ownership changes, and the father–son–grandson chain this page builds on.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"FSLI 22 ","type":"text"},{"text":"share-capital","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener noreferrer nofollow","href":"/accounting/fsli/share-capital","class":"text-primary underline cursor-pointer hover:text-primary/80","title":null,"target":"_blank"}}]},{"text":" (also covers ","type":"text"},{"text":"other-equity-component","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener noreferrer nofollow","href":"/accounting/fsli/share-capital","class":"text-primary underline cursor-pointer hover:text-primary/80","title":null,"target":"_blank"}}]},{"text":"): treasury shares under PSAK 232 and where differences from transactions with NCI sit.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"FSLI 04 ","type":"text"},{"text":"long-term-investments","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener noreferrer nofollow","href":"/accounting/fsli/long-term-investments","class":"text-primary underline cursor-pointer hover:text-primary/80","title":null,"target":"_blank"}}]},{"text":": the equity method used bottom up in each chain.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"K1 Business Combinations","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener noreferrer nofollow","href":"/accounting/consolidation/business-combinations-acquisition-method-goodwill-common-control","class":"text-primary underline cursor-pointer hover:text-primary/80","title":null,"target":"_blank"}}]},{"text":": goodwill and the NCI measurement choice.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"K2 Consolidation Worksheet","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener noreferrer nofollow","href":"/accounting/consolidation/consolidation-worksheet-elimination-entries","class":"text-primary underline cursor-pointer hover:text-primary/80","title":null,"target":"_blank"}}]},{"text":": the elimination sequence.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"K3","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener noreferrer nofollow","href":"/accounting/consolidation/intercompany-profit-in-inventory","class":"text-primary underline cursor-pointer hover:text-primary/80","title":null,"target":"_blank"}}]},{"text":" and ","type":"text"},{"text":"K4","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener noreferrer nofollow","href":"/accounting/consolidation/intercompany-profit-plant-assets","class":"text-primary underline cursor-pointer hover:text-primary/80","title":null,"target":"_blank"}}]},{"text":": the unrealised profits inside the allocation schedule.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"K5","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener noreferrer nofollow","href":"/accounting/consolidation/consolidated-cash-flows-and-mid-year-acquisitions","class":"text-primary underline cursor-pointer hover:text-primary/80","title":null,"target":"_blank"}}]},{"text":": cash flows from transactions with NCI.","type":"text"}]}]}]},{"type":"heading","attrs":{"level":3,"textAlign":null},"content":[{"text":"Least-confident assertions","type":"text"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"Reading BRPT's Note 1d is partly inference. The table gives direct holdings for Holdings BV (51 and 49 percent) but apparently effective ones elsewhere (90 percent for SEG-WW, which BREN reports as its effective interest). The ACEHI row shows \"indirect ownership through ACEHI 19.80\" while BREN shows ACEHI as an NCI holder. Linking the 4.80 percent to SEGHPL's 24.24 percent of ACEHI rests on the arithmetic matching BRPT's 80.91 percent statement. BRPT's table also gives 80.19 percent for Holdings BV's stake in SEGSDBV and no 2024 figure for the ACEHI row, although the ACEHI shares were registered in December 2023; the page uses BREN's 80.20 percent, the only figure that reproduces 80.91.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"That BRPT holds the 5 percent \"direct ownership\" of SEGSS and DGI is read from BRPT's table wording and from BREN's matching effective percentages. BREN names Barito Pacific as the holder only for SEGI and SEGH.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"How to attribute a parent's dividend paid to a subsidiary with NCI (Beams' 8,600 in profit, against 8,000 in profit plus a 600 equity transfer) is not settled by PSAK. PSAK 232 para. 33 settles presentation (treasury shares) but not whether Son's NCI shares in the parent's profit, so the conventional profit split, and this dividend point, remain policy choices.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"UU 40/2007 art. 36 bans issuing shares to a cross-holder. Whether a subsidiary may buy existing parent shares on the market is not settled by its text, and secondary sources read it differently.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"The 287 difference between BRPT's NCI in BREN and BREN's two layers has no disclosed explanation, and the split of the 153,883 bridge in section 7 between outsiders below CAP and parent-level items is not disclosed.","type":"text"}]}]}]},{"type":"heading","attrs":{"level":2,"textAlign":null},"content":[{"text":"References","type":"text"}]},{"type":"orderedList","attrs":{"type":null,"start":1},"content":[{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"PT Barito Pacific Tbk dan Entitas Anak, consolidated financial statements 31 December 2025 and 2024 (audited, USD thousand): statement of financial position (PDF p. 16); profit or loss (p. 17); changes in equity (p. 18); cash flows (p. 19); Note 1d (pp. 24–28); Note 4, control over CAP (p. 112); Note 28 (p. 211); Note 30 (pp. 212–213); Note 31, the BREN and CAP buybacks and the CDI dilution (pp. 216–217) and the ACEHI passage (p. 218); Note 34 (pp. 220–221); Note 45 (p. 235). Printed page = PDF page − 13. BRPT FS.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"PT Barito Renewables Energy Tbk dan Entitas Anak, consolidated financial statements 31 December 2025 (audited): statement of financial position (PDF p. 12); Note 1, effective interests (p. 18), Barito Pacific's 5 percent of SEGI and SEGH (pp. 25–26) and Holdings BV's 80.20 percent (p. 26); Note 19a (p. 114); Note 20 (p. 116). BRPT FS (subsidiary).","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"Lecture notes this page follows, \"AKL – Chapter 9 – Indirect and Mutual Holding\" (Rumpun Akuntansi Keuangan, 24 pp.), summarising Beams et al., ","type":"text"},{"text":"Advanced Accounting","type":"text","marks":[{"type":"italic"}]},{"text":". NOTES. Sections 1–4 follow its order (A father–son–grandson as recap, B connecting affiliates, C parent stock held by subsidiary, D mutually held subsidiary stock). Corrections made here, checked against the PDF: p. 6 worksheet labels NCI in Toy and Son swapped (9,600 is Son's, 6,000 Toy's); p. 8 Sal's separate earnings shown as 30,000 before the 5,000 deduction, should be 35,000; p. 8 Sal's entry \"Investment in Tei 40.000 ... 70% net income ... $20.000 x 20%\" should be 4,000 and 20 percent; company names drift (Pet/Pat/Pal, Tai/Tei/Tie, Pop/Pam, Son/Sun); p. 14 Pam's entry \"Investment in Sun $72.000 ... 90% Son's net income\" should be 77,400 (90% × 86,000), which the text then uses; p. 15 worksheet headed \"Pam 80% Son ... 2018\" should be 90 percent and 2017, and Son's retained earnings 304,000 and total 704,000 should be 306,000 and 706,000; p. 17 \"S = $60.000 + 0,1 ($169.231 + 0,1)\" has a stray \"+ 0,1\"; p. 17 Pam's income of 52,308 is said to equal \"90% laba dari Son ... $7.692 dikurangi 10% laba Pam ... $84.516\", which should be 90% × 76,923 = 69,231 less 10% × 169,231 = 16,923; p. 18 worksheet headed \"80% ... 2018\" should be 90 percent and 2016; p. 18 gives 2017 separate earnings of \"$1.000.000 / $900.000\" and dividends \"$400.000 / $360.000\", while pp. 19–20 use 120,000 / 80,000 and 60,000 / 40,000; p. 19 \"$210.899 x 10%\" should be 210,989, and the entry \"Investment in Son $69.890 / Investment in Son\" should credit investment income; p. 20 \"31 desember 2018\" should be 2017; p. 21 \"3 januari 3017\" should be 2017; p. 22 repeats the conversion table from p. 20 by mistake and labels \"Investment in Son (80%)\" for Set; p. 23 labels Ton's result \"U =\" and \"S = $48.495\" (should be T) and gives \"P = $179.597\" (should be 179,957, as the worksheet uses); p. 23 \"Poly\" should be Pam; p. 24 NCI at 31 December labels swapped (5,495 is Set's, 8,548 Ton's); goodwill of 25,000 and 10,000 is grossed up from the parent's price (implied value), US GAAP textbook practice; PSAK 103 uses NCI's own fair value or its proportionate share; the conventional approach's equity presentation is not available under PSAK 232, and its profit split is not addressed there. Section 5's real-group table and section 6 have no note.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"FSLI 25 ","type":"text"},{"text":"Non-Controlling Interest","type":"text","marks":[{"type":"italic"}]},{"text":", section 7 and References (corrections to AKL Chapters 3, 4, 5 and 8 already recorded there). NOTES (sibling essay).","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"PSAK 232 ","type":"text"},{"text":"Instrumen Keuangan: Penyajian","type":"text","marks":[{"type":"italic"}]},{"text":" (IAS 32), para. 33, including \"or by other members of the consolidated group\". VERIFIED (web, secondary: BCAJ, \"Gaps in GAAP: accounting of treasury shares\"; HMRC Corporate Finance Manual CFM21220; BDO IAS 32 at a glance).","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"PSAK 110 ","type":"text"},{"text":"Laporan Keuangan Konsolidasian","type":"text","marks":[{"type":"italic"}]},{"text":" (IFRS 10), para. B86(b)–(c). VERIFIED (web, secondary: ifrs-gaap.com and university lecture material quoting IFRS 10.B86). Paras. 31 and 33 (investment entities) STANDARD — NOT VERIFIED.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"PSAK 103 (IFRS 3) para. 19; PSAK 112 (IFRS 12) para. 12; PSAK 233 (IAS 33): see FSLI 25 References for para. 19 and para. 12 (VERIFIED, web). PSAK 233 treatment of treasury shares in the weighted average STANDARD — NOT VERIFIED. Renumbering per IAI (IFRS n → PSAK 100+n, IAS n → PSAK 200+n): VERIFIED (web, IAI, via FSLI 25).","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"UU 40/2007 on limited companies, art. 36(1)–(3): VERIFIED (web, pasal.id, original text; amended by UU 6/2023, consolidated text not checked). Art. 7: see FSLI 25 (art. 7(1) VERIFIED, web, secondary).","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"Beams, Anthony, Bettinghaus and Smith, ","type":"text"},{"text":"Advanced Accounting","type":"text","marks":[{"type":"italic"}]},{"text":", ch. 9, the textbook the notes summarise. Not on disk; NOT VERIFIED.","type":"text"}]}]}]}]}$j$::jsonb,
       presentation = $p${"deck":"How a group attributes profit when its companies own each other, from connecting affiliates to subsidiaries holding parent shares, worked through Barito Pacific's layered geothermal and petrochemical chains","genre":null,"author_bio":null,"references":[],"hero_caption":null,"related_fsli":["non-controlling-interest","share-capital","long-term-investments"],"key_takeaways":["In a complex structure, control decides which companies are consolidated, and the effective interest decides how their profit and net assets are split. The effective interest is found by multiplying percentages down each ownership path and adding the paths together. A company can be a subsidiary while the parent's effective interest in it is below 50 percent.","When companies own each other, each one's profit depends on the other's, so the split needs simultaneous equations. The equations add mutual profit twice. Only the shares held by outsiders, multiplied by each equation's result, add back to the group's total profit.","When a subsidiary holds shares of its parent, Beams offers two treatments, the treasury stock approach and the conventional approach. PSAK 232 treats parent shares held by any group member as treasury shares, deducted from equity at cost, so the treasury stock approach is the one that fits Indonesian standards. Holdings between subsidiaries are eliminated, and there is no treasury alternative for them."],"revision_note":null}$p$::jsonb,
       updated_at = now()
 WHERE id = 'aab4ee41-2d26-4015-85c2-6c81bba23314';
